export function getLesson(moduleIdOrTitle: string): Lesson | null {
  const normalized = moduleIdOrTitle.trim().toLowerCase().replace(/[\s_–—-]+/g, ' ');
  const full = Object.entries(FULL_LESSONS).find(([key, value]) =>
    [key, value.title].some(title => title.trim().toLowerCase().replace(/[\s_–—-]+/g, ' ') === normalized));
  if (full) return full[1];
  if (LESSONS[moduleIdOrTitle]) return LESSONS[moduleIdOrTitle];
  if (EXTRA_LESSONS[moduleIdOrTitle]) return EXTRA_LESSONS[moduleIdOrTitle];
  const lower = moduleIdOrTitle.toLowerCase();
  for (const key of Object.keys(LESSONS)) {
    if (key.toLowerCase() === lower) return LESSONS[key];
  }
  for (const key of Object.keys(EXTRA_LESSONS)) {
    if (key.toLowerCase() === lower) return EXTRA_LESSONS[key];
  }
  return null;
}

export function hasLesson(moduleIdOrTitle: string): boolean {
  return getLesson(moduleIdOrTitle) !== null;
}
